package io.github.zerohomers0.onesteplite;import android.content.*;import android.net.*;import android.os.*;import java.io.*;import java.util.*;public class DragCacheSmoke{static int n;static void check(boolean v,String m){n++;if(!v)throw new AssertionError(m);}static byte[] b(int n){byte[] x=new byte[n];Arrays.fill(x,(byte)7);return x;}public static void main(String[] a)throws Exception{Context c=new Context(java.nio.file.Files.createTempDirectory("drag").toFile());Bundle s=DragCacheStore.store(c,b(8),"图片","image/jpeg");String id=s.getString("id");Uri u=Uri.parse(s.getString("uri"));check(DragCacheStore.find(c,u)!=null,"find");check(DragCacheStore.file(c,id).isFile(),"file");DragCacheStore.discard(c,id);check(DragCacheStore.find(c,u)==null&&!DragCacheStore.file(c,id).exists(),"discard");String old=DragCacheStore.store(c,b(8),"旧图","image/png").getString("id");Uri oldUri=DragCacheStore.uri(old);ClipData staged=DragCacheStore.promoteForStage(c,new ClipData(new ClipDescription("x",new String[]{"image/png"}),new ClipData.Item(oldUri)));check(staged!=null&&!DragCacheStore.isDragUri(staged.getItemAt(0).getUri()),"promote");check(ContentInboxProvider.appended==1&&!DragCacheStore.file(c,old).exists(),"promote cleanup");System.out.println("drag cache smoke="+n+" passed");}}